def parse_line(text):
    if text == "":
        return []

    if "\n" in text:
        raise ValueError("multiple records not supported")

    fields = []
    field = ""
    i = 0
    n = len(text)
    in_quotes = False

    while i < n:
        if in_quotes:
            if text[i] == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field += '"'
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            field += text[i]
            i += 1
            continue
        else:
            if text[i] == '"':
                in_quotes = True
                i += 1
                continue
            elif text[i] == ",":
                fields.append(field)
                field = ""
                i += 1
                continue
            field += text[i]
            i += 1

    if in_quotes:
        raise ValueError("unterminated record")

    fields.append(field)
    return fields

