import csv


def parse_line(text):
    if text == "":
        return []
    try:
        rows = list(csv.reader([text]))
    except csv.Error as e:
        raise ValueError(str(e))
    if len(rows) > 1:
        raise ValueError("input contains multiple CSV records")
    return rows[0]
